-- Corrections du quiz de fin de semaine : vent_meteo.
--
-- Générées par scripts/importer-quiz.mjs. `data` porte la version adulte, 
-- `data.version_enfant` la version enfant du même sujet. Remplace `version_moniteur`
-- (même rôle, jamais exploité par un vrai choix au lancement avant ce jour).

DELETE FROM game_cards WHERE id = 'ef575a7b-b63b-4c1f-9fb3-4d7399f2f06b';
UPDATE game_cards SET related_objective_id = '17', data = '{"question":"Comment se forme le vent ?","answers":["Par la rotation de la Terre uniquement","Par des différences de pression atmosphérique : l''air se déplace des hautes vers les basses pressions","Par l''évaporation de l''eau de mer","Par la chaleur dégagée directement par le Soleil"],"correctAnswerIndex":1,"explanation":"L''air se déplace toujours d''une zone de haute pression vers une zone de basse pression. Plus l''écart est grand, plus le vent souffle fort.","version_enfant":{"question":"D''où vient le vent ?","answers":["De l''air qui se déplace d''un endroit où il y en a beaucoup vers un endroit où il y en a moins","Il est fabriqué quelque part dans le ciel","Des vagues qui poussent l''air","Du soleil qui souffle"],"correctAnswerIndex":0,"explanation":"Le vent, c''est de l''air qui bouge pour se rééquilibrer. Il n''est fabriqué nulle part, il se déplace juste."}}'::jsonb WHERE id = 'd8d14909-54d2-4650-9a6f-dc0d224441cf';
UPDATE game_cards SET related_objective_id = '18', data = '{"question":"Pourquoi le vent se lève-t-il souvent l''après-midi en été et vient-il de la mer ?","answers":["La terre chauffe plus vite que la mer : l''air chaud monte, l''air frais de la mer prend sa place","La mer est plus salée l''après-midi","Les vagues poussent l''air","C''est le hasard"],"correctAnswerIndex":0,"explanation":"En journée, la terre chauffe plus vite que la mer. L''air chaud au-dessus du sol monte, laissant la place à l''air frais du large : c''est la brise de mer.","version_enfant":{"question":"L''après-midi en été, le vent se lève souvent et vient de la mer. Pourquoi ?","answers":["Parce que la terre chauffe plus vite que la mer","Parce que la mer est plus salée l''après-midi","Parce que les vagues poussent l''air","C''est le hasard"],"correctAnswerIndex":0,"explanation":"Le soleil chauffe la terre plus vite que l''eau. L''air chaud monte au-dessus de la plage, et l''air frais de la mer vient prendre sa place : ça fait du vent."}}'::jsonb WHERE id = 'dc47a382-c73e-44ff-904f-ac225f9b1127';
UPDATE game_cards SET related_objective_id = '19', data = '{"question":"Que signifie un vent de terre pour un pratiquant côtier ?","answers":["Un vent de la mer vers la plage, favorable au retour","Un vent de la côte vers le large, qui peut éloigner du bord sans qu''on le sente","Un vent parallèle à la côte, sans danger","Un vent variable et faible"],"correctAnswerIndex":1,"explanation":"Le vent de terre pousse vers le large sans qu''on s''en rende toujours compte près du bord — c''est le plus traître, il peut rendre le retour impossible en pagayant.","version_enfant":{"question":"Lequel est le plus dangereux : le vent qui souffle vers toi, ou celui qui souffle dans ton dos vers le large ?","answers":["Celui qui souffle vers toi","Celui qui souffle vers le large, dans ton dos","Les deux sont pareils","Aucun des deux n''est dangereux"],"correctAnswerIndex":1,"explanation":"Le vent qui pousse doucement vers le large est le plus traître : on ne le sent pas au départ, et le retour devient très difficile."}}'::jsonb WHERE id = '9486d49a-5084-40f3-a12a-806733ec9276';
UPDATE game_cards SET related_objective_id = '20', data = '{"question":"Comment repère-t-on la direction du vent sans instrument ?","answers":["En regardant uniquement la direction des vagues","En observant drapeau, fumée et rides sur l''eau — tous pointent la direction du vent","En observant uniquement le sens des nuages","En regardant où volent les mouettes"],"correctAnswerIndex":1,"explanation":"Le vent laisse des traces visibles : drapeau qui claque, fumée qui dérive, rides sur l''eau. Il suffit de remonter le fil.","version_enfant":{"question":"Comment on sait d''où vient le vent, sans instrument ?","answers":["En regardant seulement les vagues","En regardant le drapeau, la fumée, les rides sur l''eau","En regardant seulement les nuages","Il faut forcément un appareil"],"correctAnswerIndex":1,"explanation":"Le vent laisse des traces partout. Il suffit de regarder ce qui bouge autour de nous et de remonter le fil."}}'::jsonb WHERE id = '4428a4d1-b7ab-4f58-b1f6-a8bc5ac6ac97';
UPDATE game_cards SET related_objective_id = '40', data = '{"question":"Qu''indique une chute rapide de la pression atmosphérique ?","answers":["Du beau temps stable à venir","Une probable dégradation météo rapide (arrivée d''une dépression)","Un changement de marée imminent","Une remontée de vent de terre"],"correctAnswerIndex":1,"explanation":"Une chute rapide de la pression annonce l''arrivée d''une dépression, avec vent, pluie et mer agitée.","version_enfant":{"question":"En mer, le temps peut-il changer vite ?","answers":["Non, jamais","Oui, en quelques dizaines de minutes seulement","Seulement en hiver","Seulement loin des côtes"],"correctAnswerIndex":1,"explanation":"En mer, rien n''arrête le mauvais temps : il peut arriver en quelques dizaines de minutes. On regarde la météo avant de partir, et le ciel pendant."}}'::jsonb WHERE id = '2290bbe7-8fea-4582-ad06-5416a32a6ab5';
UPDATE game_cards SET related_objective_id = '40', data = '{"question":"Pourquoi le temps change-t-il plus vite en mer qu''à terre ?","answers":["L''air marin est plus léger et se déplace plus vite","Aucun relief ne freine les systèmes météo, qui se déplacent librement","Les vagues accélèrent le déplacement des nuages","L''eau salée conduit mieux la chaleur"],"correctAnswerIndex":1,"explanation":"En mer, aucun relief ne freine les dépressions et fronts : ils peuvent faire basculer les conditions en quelques dizaines de minutes.","version_enfant":{"question":"Pourquoi la météo change plus vite sur l''eau qu''au village ?","answers":["Rien n''arrête le mauvais temps qui arrive : ni colline, ni immeuble","L''air de la mer est plus léger","Les vagues poussent les nuages plus vite","L''eau salée fait courir les nuages"],"correctAnswerIndex":0,"explanation":"En mer, rien ne freine le mauvais temps qui arrive. On regarde la météo avant de partir, et on garde un œil sur le ciel pendant la séance."}}'::jsonb WHERE id = 'd89ef082-fb26-4790-8075-ff4b41aece60';
UPDATE game_cards SET related_objective_id = '99', data = '{"question":"Comment se forme un nuage ?","answers":["De la vapeur d''eau brûlante qui monte directement du sol","L''air chaud et humide monte, se refroidit, et la vapeur se condense autour de particules en suspension","Le vent pousse l''humidité vers le haut","La pluie s''évapore avant d''atteindre le sol"],"correctAnswerIndex":1,"explanation":"L''air chaud monte, se refroidit en altitude, ne peut plus retenir autant de vapeur d''eau : elle se condense en gouttelettes autour de poussières ou de sel marin.","version_enfant":{"question":"Un nuage, c''est fait de quoi ?","answers":["De fumée","De minuscules gouttes d''eau qui flottent dans l''air","De vapeur invisible","De coton"],"correctAnswerIndex":1,"explanation":"L''eau de la mer s''évapore, monte, refroidit et se transforme en minuscules gouttelettes : c''est le nuage."}}'::jsonb WHERE id = 'c8e42ed6-91fd-49c1-8c4d-e89ad43eaea0';
UPDATE game_cards SET related_objective_id = '115', data = '{"question":"Quel type de nuage annonce souvent des orages et des conditions instables ?","answers":["Le stratus (nappe grise basse)","Le cirrus (filaments blancs en altitude)","Le cumulonimbus (développement vertical imposant)","L''altocumulus (moutons blancs à altitude moyenne)"],"correctAnswerIndex":2,"explanation":"Le cumulonimbus est le nuage d''orage par excellence : son sommet dépasse souvent 10 km et peut atteindre 18 km, bien au-dessus de l''altitude des avions de ligne.","version_enfant":{"question":"Comment reconnaît-on le nuage qui annonce un orage ?","answers":["Il est fin et étiré, en filaments","Il monte très haut, avec une base sombre et un sommet en enclume","Il forme une nappe grise uniforme","Il est toujours tout blanc"],"correctAnswerIndex":1,"explanation":"Le cumulonimbus monte plus haut que les avions et sa base est sombre. Il annonce pluie forte, grêle ou orage."}}'::jsonb WHERE id = '77642f8f-b66f-497e-9e08-ec89d2211286';
